// Literal, deterministic pronunciation modifiers. Original orthographic segments never change.
const SEGMENT_CONNECTION_STORAGE_KEY = 'reorite3_segment_connection_rules';

function defaultSegmentConnectionRules(){
  return [{id:'stress-before-r',name:'Example: stress before an r segment',enabled:false,
    field:'ipa',action:'prepend',characters:'ˈ',replacement:'',skipIfPresent:true,
    target:{shapes:['C','CV','CVV'],startsWith:'r'},previous:{},previousScope:'adjacent',
    next:null,nextScope:'adjacent',position:'any',wordStartsWith:'',wordEndsWith:''}];
}

function getSegmentShape(value){
  return String(value||'').normalize('NFC').toLowerCase().replace(/ng|wh/g,'C')
    .replace(/[aeiouāēīōū]/g,'V').replace(/[a-z]/g,'C');
}

function normalizeSegmentConnectionRules(input){
  if(!Array.isArray(input) || input.length>100)throw new Error('Use an array of at most 100 connection modifiers.');
  const ids=new Set();
  function text(value,max=100){
    if(typeof value!=='string' || value.length>max || /[\u0000-\u001f]/.test(value))throw new Error('Modifier text is invalid or too long.');
    return value.normalize('NFC');
  }
  function matcher(value){
    if(value==null)return null;
    if(typeof value!=='object' || Array.isArray(value))throw new Error('Invalid segment criteria.');
    for(const key of Object.keys(value))if(!['shapes','startsWith','endsWith','contains','equals','not'].includes(key))throw new Error('Unknown segment criterion: '+key);
    const shapes=value.shapes??[];
    if(!Array.isArray(shapes) || shapes.length>20 || shapes.some(shape=>typeof shape!=='string' || !/^[CV]{1,12}$/i.test(shape)))throw new Error('Shapes must contain C and V only, such as C, V, CV or CVV.');
    if(value.not!=null && typeof value.not!=='boolean')throw new Error('Negate must be a Boolean.');
    const out={shapes:[...new Set(shapes.map(s=>s.toUpperCase()))],not:!!value.not};
    for(const key of ['startsWith','endsWith','contains','equals'])out[key]=text(value[key]||'',50).toLowerCase();
    return out;
  }
  return input.map(rule=>{
    if(!rule || typeof rule!=='object' || Array.isArray(rule))throw new Error('Invalid modifier.');
    for(const key of Object.keys(rule))if(!['id','name','enabled','field','action','characters','replacement','skipIfPresent','target','previous','next','previousScope','nextScope','position','wordStartsWith','wordEndsWith'].includes(key))throw new Error('Unknown modifier option: '+key);
    if(typeof rule.id!=='string' || !/^[a-z0-9][a-z0-9-]{0,79}$/.test(rule.id) || ids.has(rule.id))throw new Error('Modifier IDs must be unique lowercase letters, numbers and hyphens.');ids.add(rule.id);
    if(typeof rule.enabled!=='boolean')throw new Error('Each modifier needs an enabled Boolean.');
    const name=text(rule.name,100).trim();if(!name)throw new Error('Enter a modifier name.');
    const field=rule.field||'ipa',action=rule.action||'prepend',position=rule.position||'any';
    if(!['ipa','phonetic'].includes(field) || !['prepend','append','remove-start','remove-end','remove-all','replace'].includes(action) || !['any','first','last','middle'].includes(position))throw new Error('Invalid modifier field, action or position.');
    const characters=text(rule.characters,100);if(!characters)throw new Error('Enter characters to add, remove or replace.');
    if(rule.skipIfPresent!=null && typeof rule.skipIfPresent!=='boolean')throw new Error('Skip if present must be a Boolean.');
    const previousScope=rule.previousScope||'adjacent',nextScope=rule.nextScope||'adjacent';
    if(!['adjacent','any'].includes(previousScope) || !['adjacent','any'].includes(nextScope))throw new Error('Invalid neighbour scope.');
    return {id:rule.id,name,enabled:rule.enabled,field,action,characters,replacement:text(rule.replacement||'',100),skipIfPresent:rule.skipIfPresent!==false,
      target:matcher(rule.target||{}),previous:matcher(rule.previous),next:matcher(rule.next),previousScope,nextScope,position,
      wordStartsWith:text(rule.wordStartsWith||'',100).toLowerCase(),wordEndsWith:text(rule.wordEndsWith||'',100).toLowerCase()};
  });
}

function loadSegmentConnectionRules(){
  try{
    const raw=typeof loadFromStorage==='function'?loadFromStorage(SEGMENT_CONNECTION_STORAGE_KEY):'';
    return normalizeSegmentConnectionRules(raw?JSON.parse(raw):defaultSegmentConnectionRules());
  }catch(_){return normalizeSegmentConnectionRules(defaultSegmentConnectionRules());}
}

function segmentMatchesConnectionCriteria(segment,criteria){
  if(!criteria)return true;
  const value=String(segment||'').normalize('NFC').toLowerCase();
  let match=(!criteria.shapes.length || criteria.shapes.includes(getSegmentShape(value)))
    && (!criteria.startsWith || value.startsWith(criteria.startsWith))
    && (!criteria.endsWith || value.endsWith(criteria.endsWith))
    && (!criteria.contains || value.includes(criteria.contains))
    && (!criteria.equals || value===criteria.equals);
  return criteria.not?!match:match;
}

function applySegmentConnections(segments,inputRows,rules=loadSegmentConnectionRules()){
  const normalized=normalizeSegmentConnectionRules(rules),rows=inputRows.map(row=>({...row})),changes=[];
  const original=segments.map(segment=>String(segment).normalize('NFC').toLowerCase()),word=original.join('');
  if(rows.length!==original.length)throw new Error('Modifier rows must align with original segments.');
  for(const rule of normalized){
    if(!rule.enabled)continue;
    for(let i=0;i<rows.length;i++){
      if(rule.position==='first' && i!==0 || rule.position==='last' && i!==rows.length-1 || rule.position==='middle' && (i===0 || i===rows.length-1))continue;
      if(!word.startsWith(rule.wordStartsWith) || !word.endsWith(rule.wordEndsWith) || !segmentMatchesConnectionCriteria(original[i],rule.target))continue;
      const neighbour=(criteria,scope,before)=>{
        if(!criteria)return true;
        const candidates=before?original.slice(0,i):original.slice(i+1);
        if(scope==='adjacent')return !!candidates.length && segmentMatchesConnectionCriteria(before?candidates.at(-1):candidates[0],criteria);
        return candidates.some(segment=>segmentMatchesConnectionCriteria(segment,criteria));
      };
      if(!neighbour(rule.previous,rule.previousScope,true) || !neighbour(rule.next,rule.nextScope,false))continue;
      const key=rule.field==='ipa'?'chosenIpa':'chosenPhonetic',before=String(rows[i][key]||'');
      // Never turn a missing lookup into an invented pronunciation.
      if(!before || rows[i].status==='missing')continue;
      const chars=rule.characters;let after=before;
      if(rule.action==='prepend' && !(rule.skipIfPresent && before.startsWith(chars)))after=chars+before;
      else if(rule.action==='append' && !(rule.skipIfPresent && before.endsWith(chars)))after=before+chars;
      else if(rule.action==='remove-start' && before.startsWith(chars))after=before.slice(chars.length);
      else if(rule.action==='remove-end' && before.endsWith(chars))after=before.slice(0,-chars.length);
      else if(rule.action==='remove-all')after=before.split(chars).join('');
      else if(rule.action==='replace')after=before.split(chars).join(rule.replacement);
      if(after!==before){rows[i][key]=after;changes.push({id:'SC-'+rule.id,name:rule.name,index:i,segment:original[i],field:rule.field,before,after});}
    }
  }
  return {rows,changes};
}

